#include <stdio.h>

int main() {
    float a, b, c;
    printf("Enter three numbers: ");
    scanf("%f %f %f", &a, &b, &c);

    if (a >= b && a >= c) {
        printf("Largest number is %.2f\n", a);
    } else if (b >= a && b >= c) {
        printf("Largest number is %.2f\n", b);
    } else {
        printf("Largest number is %.2f\n", c);
    }
    return 0;
}
```

### Logic Explanation
The program uses logical AND (`&&`) operators inside nested `if-else` relational checks to compare the three numbers (`a`, `b`, and `c`):
1. If `a` is greater than or equal to both `b` and `c`, then `a` is the largest.
2. Otherwise, if `b` is greater than or equal to both `a` and `c`, then `b` is the largest.
3. If neither condition is true, `c` must be the largest number.
